+fn vid(pt: Point3, s: f64, verts: &mut Vec<Point3>, ids: &mut HashMap<(i64, i64, i64), usize>) -> usize {
+    let k = vkey(pt, s);
+    if let Some(&i) = ids.get(&k) {
+        return i;
+    }
+    let i = verts.len();
+    verts.push(pt);
+    ids.insert(k, i);
+    i
+}

