+                if !q.is_finite() {
+                    return None;
+                }
+                next.push(q);
+            }
+            if dc <= 0.0 {
+                next.push(cur);
+            }
+            prev = cur;
+            dp = dc;
+        }
+        poly = next;
+    }
+    Some(poly)
